mapper.select:
SELECT s.seat_id, s.hall_id, s.row_num, s.col_num, s.seat_code, s.seat_type, s.status
FROM seat s
WHERE s.hall_id = #{hallId}
  AND s.seat_id NOT IN (
      SELECT os.seat_id FROM order_seat os
      JOIN order_ticket ot ON os.order_id = ot.order_id
      WHERE ot.screening_id = #{screeningId}
        AND ot.status IN (0, 1)
  )
ORDER BY s.row_num, s.col_num

mapper.update:
UPDATE seat
hall_id = #{hallId}, row_num = #{rowNum}, col_num = #{colNum}, seat_code = #{seatCode}, seat_type = #{seatType}, status = #{status},
WHERE seat_id = #{seatId}
